// The typed SDK of the Rust API. `web/lib/api` is generated by
// @hey-api/openapi-ts from the OpenAPI document that the Rust handlers produce
// (`vp run generate:api`), so a change on either side shows up as a type error
// here. Its client sends every request to https://rust.fetchlet.test, which
// global `fetch` delivers to the axum router inside the same process, with no
// socket; the Rust fetch policy admits no other origin.
export * as rust from "#lib/api/sdk.gen.ts";
